import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#020617', card: '#0f172a', accent: '#38bdf8', 
  gold: '#fbbf24', text: '#f8fafc', muted: '#94a3b8', 
  border: '#1e293b', success: '#22c55e', danger: '#ef4444'
};

export default function App() {
  const [tab, setTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v4_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  const [novoProc, setNovoProc] = useState({ cliente: '', numero: '', valor: '', data: '', status: 'Ativo' });

  useEffect(() => {
    localStorage.setItem('juris_v4_data', JSON.stringify(processos));
  }, [processos]);

  // Função para calcular prazos (15 dias úteis padrão CPC)
  const calcularPrazo = (dataInicial) => {
    if (!dataInicial) return '---';
    let data = new Date(dataInicial + 'T00:00:00');
    let diasUteis = 0;
    while (diasUteis < 15) {
      data.setDate(data.getDate() + 1);
      if (data.getDay() !== 0 && data.getDay() !== 6) diasUteis++;
    }
    return data.toLocaleDateString('pt-BR');
  };

  const addProcesso = () => {
    if (!novoProc.cliente || !novoProc.valor) return alert("Preencha os dados do processo!");
    setProcessos([...processos, { ...novoProc, id: Date.now() }]);
    setNovoProc({ cliente: '', numero: '', valor: '', data: '', status: 'Ativo' });
    setTab('dashboard');
  };

  const totalHonorarios = processos.reduce((acc, p) => acc + Number(p.valor || 0), 0);

  return (
    <div style={s.app}>
      {/* SIDEBAR DESIGN PREMIUM */}
      <aside style={s.sidebar}>
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard</div>
          <div style={s.navLink(tab === 'processos')} onClick={() => setTab('processos')}>📂 Meus Processos</div>
          <div style={s.navLink(tab === 'novo')} onClick={() => setTab('novo')}>➕ Novo Processo</div>
        </nav>
        <div style={s.licenseCard}>
          <div style={{fontSize: '11px', color: COLORS.gold, marginBottom: '5px'}}>PLANO ANUAL</div>
          <div style={{fontSize: '13px'}}>Renovação: 14/05/2027</div>
        </div>
      </aside>

      <main style={s.content}>
        <header style={s.header}>
          <div>
            <h2 style={{margin: 0}}>Painel Administrativo</h2>
            <p style={{color: COLORS.muted, margin: '5px 0 0'}}>Bem-vindo, Dr. Rodrigo. Gerencie sua banca jurídica.</p>
          </div>
          <div style={s.dateBadge}>14 de maio de 2026</div>
        </header>

        {/* DASHBOARD - KPI's FINANCEIROS */}
        {tab === 'dashboard' && (
          <div style={s.grid}>
            <StatCard label="Honorários em Carteira" value={`R$ ${totalHonorarios.toLocaleString('pt-BR')}`} color={COLORS.success} />
            <StatCard label="Processos Ativos" value={processos.length} color={COLORS.accent} />
            <StatCard label="Prazos Críticos" value={processos.filter(p => p.data !== '').length} color={COLORS.danger} />

            <div style={{...s.card, gridColumn: 'span 3'}}>
              <h3 style={{marginTop: 0}}>Resumo de Processos Recentes</h3>
              <div style={s.tableContainer}>
                <table style={s.table}>
                  <thead>
                    <tr>
                      <th style={s.th}>Cliente</th>
                      <th style={s.th}>Nº Processo</th>
                      <th style={s.th}>Vencimento CPC</th>
                      <th style={s.th}>Honorários</th>
                    </tr>
                  </thead>
                  <tbody>
                    {processos.map(p => (
                      <tr key={p.id}>
                        <td style={s.td}>{p.cliente}</td>
                        <td style={s.td}>{p.numero}</td>
                        <td style={s.td}><span style={s.deadlineBadge}>{calcularPrazo(p.data)}</span></td>
                        <td style={s.td}>R$ {Number(p.valor).toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* TELA DE CADASTRO PROFISSIONAL */}
        {tab === 'novo' && (
          <div style={{...s.card, maxWidth: '600px', margin: '0 auto'}}>
            <h3 style={{color: COLORS.accent, marginTop: 0}}>➕ Registrar Novo Caso</h3>
            <div style={s.formGrid}>
              <div style={s.inputGroup}>
                <label style={s.label}>Nome do Cliente</label>
                <input style={s.input} value={novoProc.cliente} onChange={e => setNovoProc({...novoProc, cliente: e.target.value})} placeholder="Ex: Maria Silva" />
              </div>
              <div style={s.inputGroup}>
                <label style={s.label}>Número do Processo</label>
                <input style={s.input} value={novoProc.numero} onChange={e => setNovoProc({...novoProc, numero: e.target.value})} placeholder="0000000-00.2026.8..." />
              </div>
              <div style={s.inputGroup}>
                <label style={s.label}>Honorários Acordados (R$)</label>
                <input style={s.input} type="number" value={novoProc.valor} onChange={e => setNovoProc({...novoProc, valor: e.target.value})} placeholder="5000" />
              </div>
              <div style={s.inputGroup}>
                <label style={s.label}>Data da Intimação (Início do Prazo)</label>
                <input style={s.input} type="date" value={novoProc.data} onChange={e => setNovoProc({...novoProc, data: e.target.value})} />
              </div>
            </div>
            <button style={s.btnMain} onClick={addProcesso}>SALVAR NO SISTEMA</button>
          </div>
        )}
      </main>
    </div>
  );
}

// COMPONENTES AUXILIARES
const StatCard = ({label, value, color}) => (
  <div style={s.card}>
    <div style={{color: COLORS.muted, fontSize: '13px', fontWeight: 'bold'}}>{label.toUpperCase()}</div>
    <div style={{fontSize: '32px', fontWeight: 'bold', color: color, margin: '15px 0'}}>{value}</div>
    <div style={{height: '4px', background: color, borderRadius: '2px', width: '40%'}} />
  </div>
);

